// test_model.mjs -- verifies public/js/model.js's forward() reproduces the
// Python/torch model (via ml/export.py:predict_from_json) to 1e-5 on ~100
// random inputs (fixtures/model_vectors.json, generated by gen_reference.py).
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { prepareModel, forward } from "../public/js/model.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const TOL = 1e-5;

function main() {
  const modelObj = JSON.parse(readFileSync(join(__dirname, "../public/data/model.json"), "utf-8"));
  const model = prepareModel(modelObj);
  const fixtures = JSON.parse(readFileSync(join(__dirname, "fixtures/model_vectors.json"), "utf-8"));

  let maxDiff = 0, maxDiffName = "", nChecked = 0;
  const perField = {};
  for (const c of fixtures.cases) {
    const out = forward(model, c.x, c.y, c.z, c.theta_deg, c.sdf, c.height);
    for (const [name, expected] of Object.entries(c.expected)) {
      const diff = Math.abs(out[name] - expected);
      perField[name] = Math.max(perField[name] || 0, diff);
      if (diff > maxDiff) { maxDiff = diff; maxDiffName = name; }
      nChecked++;
    }
  }

  console.log(`[test_model] ${fixtures.n} casos, ${nChecked} valores comparados`);
  for (const [name, d] of Object.entries(perField)) console.log(`  ${name}: max|diff| = ${d.toExponential(3)}`);
  console.log(`  peor caso: ${maxDiffName} = ${maxDiff.toExponential(3)} (tolerancia ${TOL})`);

  if (maxDiff >= TOL) {
    console.error(`FALLO: diferencia maxima ${maxDiff} >= ${TOL}`);
    process.exit(1);
  }
  console.log("OK: JS reproduce el modelo Python/torch dentro de 1e-5.");
}

main();
